#include <stdio.h>

int main(void)
{
    int coefficients[] = {1, 2, 1};
    int terms = 0;
    for (int i = 0; i < 3; i++) {
        terms += coefficients[i] != 0;
    }
    printf("%d\n", terms);
    return 0;
